import React, {useState} from 'react';
import {usersCollection} from '../firebase/Firebase';
import {doc, getDocs, query, setDoc, where} from 'firebase/firestore';
import {useNavigate} from 'react-router-dom';
import {Button, Container, Form, Modal} from 'react-bootstrap';
import ValidateFn from '../components/ValidationFn';
import {doPasswordChange, doSignInWithEmailAndPassword, updateUserDisplayName} from "../firebase/auth";
import {useAuth} from "../contexts/authContext";

// import { useAuth } from "../contexts/authContext";

function Login({setIsLoggedIn, setUserInfo}) {
    // const { userLoggedIn } = useAuth();
    const navigate = useNavigate();
    const loggedInUserId = localStorage.getItem('userId');

    const [user, setUser] = useState([])

    const [loginInfo, setLoginInfo] = useState({
        username: '',
        password: ''
    });

    const [changePwd, setChangePwd] = useState({
        oldPwd: '',
        newPwd: '',
        confirmNewPwd: ""
    });

    const [isSigningIn, setIsSigningIn] = useState(false);

    const [formDataError, setFormDataError] = useState('');
    const [formPwdChgError, setFormPwdChgError] = useState('');
    const [isUserNotDoneRegistering, setUserNotDoneRegistering] = useState(false);

    const getLoginInfo = async () => {
        try {
            const q = query(usersCollection,
                where("email", "==", loginInfo.username),
                where("password", "==", loginInfo.password));

            const querySnapshot = await getDocs(q);
            const info = querySnapshot.docs.find((val, idx) => idx === 0);
            if (info.data() != null) {
                setUser(info.data());

                console.log("user id in login is: " + info.id)
                const firstName = info.data().firstName;
                const lastName = info.data().lastName;
                const id = info.id;
                localStorage.setItem('isLoggedIn', 'true');
                localStorage.setItem('userId', info.id);
                localStorage.setItem('firstName', firstName);
                localStorage.setItem('lastName', lastName);
                setUserInfo({firstName, lastName});
                setIsLoggedIn(true);

                // Check it its the first time the user logs in
                if (!info.data().finishedRegistering) {
                    // Finish registering
                    setUserNotDoneRegistering(true);
                } else {
                    navigate("/");
                }
            }

        } catch (e) {
            console.error("Error occured. ", e);
            localStorage.setItem('isLoggedIn', 'false');
            localStorage.setItem('userId', '');
            localStorage.setItem('firstName', '');
            localStorage.setItem('lastName', '');
            setFormDataError('The credentials entered are invalid.')

        }
    }
    const getUserInfo = async (user) => {
        try {
            const q = query(usersCollection,
                where("email", "==", user.email));
            // ,
            //     where("password", "==", loginInfo.password));

            const querySnapshot = await getDocs(q);
            // Get the first instance
            const info = querySnapshot.docs.find((val, idx) => idx === 0);
            if (info.data() != null) {
                setUser(info.data());

                console.log("user id in login is: " + info.id)
                const firstName = info.data().firstName;
                const lastName = info.data().lastName;
                const displayName = (lastName + ", " + firstName);
                const id = info.id;
                const type = info.data().type;
                localStorage.setItem('isLoggedIn', 'true');
                localStorage.setItem('displayedName', displayName);
                localStorage.setItem('type', type);
                localStorage.setItem('userId', info.id); // to later get access to the user
                // localStorage.setItem('firstName', firstName);
                // localStorage.setItem('lastName', lastName);
                setUserInfo({displayName, type});
                // setUserInfo({ firstName, lastName})
                setIsLoggedIn(true);
                // if (user.displayName==='' || user.displayName === null) {
                //     updateUserDisplayName(displayName);
                // }
                // Check it its the first time the user logs in
                if (!info.data().finishedRegistering) {
                    // Email has not been verified and user did not finish registering
                    setUserNotDoneRegistering(true);
                } else {
                    // Finished registering

                }


            }

        } catch (e) {
            console.error("Error occured. ", e);
            localStorage.setItem('isLoggedIn', 'false');
            localStorage.setItem('userId', '');
            localStorage.setItem('displayedName', '');
            localStorage.setItem('type', '');

            // localStorage.setItem('firstName', '');
            // localStorage.setItem('lastName', '');
            setFormDataError('The credentials entered are invalid.')
        }
    }

    const handleLogin = async (event) => {
        event.preventDefault();
        if (!isSigningIn) {
            await doSignInWithEmailAndPassword(loginInfo.username, loginInfo.password).then((userInfo) => {
                console.log("OK. IT WORKS", userInfo)
                setIsSigningIn(true);
                getUserInfo(userInfo.user);

                console.log("line 114")
                navigate("/");
            }).catch((e) => {
                setFormDataError('The credentials entered are invalid.')
                setLoginInfo({
                    username: '',
                    password: ''
                })

                console.log("Not working. ", e);
            });

        }
        // getLoginInfo();
    };

    const handleChange = (event) => {
        const target = event.target;
        const value = target.value;
        const name = target.name;
        setLoginInfo({...loginInfo, [name]: value});
    }

    const handleModalClose = () => {
        setUserNotDoneRegistering(false);
    };

    const handlePwdChange = (event) => {
        const target = event.target;
        const value = target.value;
        const name = target.name;
        setChangePwd({...changePwd, [name]: value});
    }

    const handlePwdChgSubmit = (e) => {
        e.preventDefault();
        pwdChgSubmit();
    }

    const pwdChgSubmit = async () => {
        const validatePwdChg = ValidateFn.validatePwdChange(changePwd);
        setFormPwdChgError(validatePwdChg);

        let flag = false;

        for (let i = 0; i < validatePwdChg.length; i++) {
            if (validatePwdChg[i] !== "") {
                flag = true;
            }
        }

        if (!flag) {
            // Make sure to change the password for the authentication
            await doPasswordChange(changePwd.newPwd).then((r) => {
                // Finished registering
                const docRef = doc(usersCollection, loggedInUserId);
                // const docSnap = await getDoc(docRef);
                setDoc(docRef, {'finishedRegistering': true}, {merge: true});
                // Close modal
                setUserNotDoneRegistering(false);
                // Navigate back to the main page
                navigate("/");
            }).catch((e) => {
                console.error("There was an error. Cannot complete password change", e);
            })

        }
    }

    const [forgotPwd, setForgotPwd] = useState(false);

    const forgotPassword = () => {
        setForgotPwd(true);
    }

    return (
        <>
            <Container>
                {!forgotPwd ?
                    <form className="loginPage align-middle border p-2">

                        <h3 className='mt-3 fw-bold' id="usersDataContainer">Sign In</h3>
                        <div className=" d-flex flex-column">
                            <tr className='text-start mx-md-2'>
                                <label
                                    htmlFor="username"
                                    className="form-label text-start fw-medium"
                                >Email address</label>
                                <Form.Control
                                    type="text"
                                    className="form-control border"
                                    id="username"
                                    name="username"
                                    placeholder={"Enter email"}
                                    value={loginInfo.username}
                                    onChange={handleChange}
                                />
                            </tr>
                            <tr className='text-start mt-3 mb-0 mx-md-2'>
                                <label htmlFor="password" className="form-label fw-medium">Password</label>
                                <Form.Control
                                    type="password"
                                    className="form-control border"
                                    id="password"
                                    name="password"
                                    placeholder={"Enter password"}
                                    value={loginInfo.password}
                                    onChange={handleChange}
                                />
                                {formDataError !== "" ? (
                                    <div className="invalidInput mt-1 ps-1" style={{color: "red"}}>{formDataError}</div>
                                ) : (
                                    <></>
                                )}
                                {/*<p className={"text-end mt-2"}*/}
                                {/*   style={{fontSize: '14px', cursor: 'pointer', color: '#3f48cc'}}*/}
                                {/*   onClick={forgotPassword}>Forgot Password?</p>*/}
                            </tr>
                            <tr className='text-start mt-4 mx-md-2'>
                                <Button className='m-0 mt-0 dataMenuBtn w-100' type="submit"
                                        onClick={handleLogin}>Login</Button>
                            </tr>

                        </div>

                    </form>
                    :
                    <form className="loginPage align-middle border p-2">

                        <h4 className='mt-3 fw-bold' id="usersDataContainer">Forgot Password</h4>
                        <div className=" d-flex flex-column">
                            <tr className='text-start mx-md-2'>
                                <label
                                    htmlFor="username"
                                    className="form-label text-start fw-medium"
                                >Email address</label>
                                <Form.Control
                                    type="text"
                                    className="form-control border"
                                    id="username"
                                    name="username"
                                    placeholder={"Enter email"}
                                    value={loginInfo.username}
                                    onChange={handleChange}
                                />
                                {formDataError !== "" ? (
                                    <div className="invalidInput mt-1 ps-1" style={{color: "red"}}>{formDataError}</div>
                                ) : (
                                    <></>
                                )}
                            </tr>

                            <tr className='text-start mt-3 mx-md-2'>
                                <Button className='m-0 mt-0 dataMenuBtn w-100' type="submit"
                                        onClick={handleLogin}>Send Email</Button>
                            </tr>

                        </div>

                    </form>
                }
                    </Container>

                    <Modal
                    show={isUserNotDoneRegistering}
                onHide={handleModalClose}
                size="lg"
                backdrop="static"
                keyboard={false}
                scrollable
            >
                <Modal.Header>
                    <Modal.Title>Action Required</Modal.Title>
                </Modal.Header>
                <Modal.Body className="text-center">
                    <h5>To complete your registration, please change your password.</h5>
                    <div className=" d-flex flex-column">
                        <tr className='text-start mt-3 mx-md-2'>
                            <label htmlFor="newPwd" className="form-label">New password</label>
                            <Form.Control
                                type="password"
                                className="form-control border"
                                id="newPwd"
                                name="newPwd"
                                value={changePwd.newPwd}
                                onChange={handlePwdChange}
                            />
                            {formPwdChgError[0] !== "" ? (
                                <div className="invalidInput mt-1" style={{color: "red"}}>{formPwdChgError[0]}</div>
                            ) : (
                                <></>
                            )}
                        </tr>
                        <tr className='text-start mt-3 mx-md-2'>
                            <label htmlFor="confirmNewPwd" className="form-label">Confirm new password</label>
                            <Form.Control
                                type="password"
                                className="form-control border"
                                id="confirmNewPwd"
                                name="confirmNewPwd"
                                value={changePwd.confirmNewPwd}
                                onChange={handlePwdChange}
                            />
                            {formPwdChgError[1] !== "" ? (
                                <div className="invalidInput mt-1" style={{color: "red"}}>{formPwdChgError[1]}</div>
                            ) : (
                                <></>
                            )}
                        </tr>
                    </div>
                    <button className='mt-3 mb-3' type='submit' onClick={handlePwdChgSubmit}>Finish Registration
                    </button>
                </Modal.Body>
            </Modal>
        </>
    )
}

export default Login;